generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  FILTER EXISTS {
    ?cf a wm:CashFlow ;
        wm:investorId ?investorId ;
        wm:type ?cfType .
    FILTER(CONTAINS(LCASE(?cfType), "redemption"))
  }

  FILTER EXISTS {
    ?ra a wm:RebalancingAction ;
        wm:investorId ?investorId ;
        wm:action ?raAction .
    FILTER(CONTAINS(LCASE(?raAction), "manual override"))
  }

  FILTER EXISTS {
    ?inv wm:hasScenarioRebalancing ?scenario .
    ?scenario a wm:MarketScenario ;
              rdfs:label ?msLabel .
    FILTER(CONTAINS(LCASE(?msLabel), "flash crash"))
  }
}

